package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Entities_unescape_TriageGen1Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
        // Setup some base entities for testing
        entities.addEntity("lt", 60);
        entities.addEntity("gt", 62);
        entities.addEntity("amp", 38);
    }

















    @Test
    public void testUnescape_WithNestedAmpersandPattern() {
        // Logic: if (amph != -1 && amph < semi) -> buf.append(ch); continue;
        // This handles cases like "&...&...;" where the first '&' is not part of a valid entity
        assertEquals("&lt&gt;", entities.unescape("&lt&gt;")); 
        // In "&lt&gt;", first '&' is at 0. semi is at 3. amph is at 4. 4 < 3 is false.
        // Let's try: & & ;
        // str = "&abc&def;" 
        // i=0, ch='&'. semi=8 (after def). amph=4 (before def). 4 < 8 is true.
        // buf.append('&'). i stays 0. Loop i++ makes i=1.
        assertEquals("&abc&def;", entities.unescape("&abc&def;"));
    }








}

