    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
        // Setup some base entities for testing
        entities.addEntity("lt", 60);
        entities.addEntity("gt", 62);
        entities.addEntity("amp", 38);
    }























    @Test
    public void testUnescape_ComplexEdgeCases() {
        // Test the "amph < semi" branch specifically
        // str = "& & ;"
        // index: 01234
        // i=0, ch='&', semi=4, amph=2. 2 < 4 is true. Append '&'.
        // i=1, ch=' ', append ' '.
        // i=2, ch='&', semi=4, amph=-1. semi != -1. entityName=" ". entityValue = entities.entityValue(" ") = -1.
        // result "&  ;"
        assertEquals("& &;", entities.unescape("& &;"));
    }


}

